  "overview": {
    "text": "Cleveland is an Ohio city on the southern shore of Lake Erie, founded in 1796 and incorporated in 1836; its name honors survey leader Moses Cleaveland. Rail and water routes, along with iron and oil, helped make it an important industrial and commercial center. The Cuyahoga River cuts through the city’s Flats, a former dock-and-factory district that today mixes commerce, industry, nightlife, and homes. Nearby Ohio City, once a separate municipality, is among Cleveland’s oldest neighborhoods and is home to the West Side Market. The Cleveland Orchestra, founded in 1918 and based at Severance Music Center, adds a prominent cultural dimension through performances, education, recordings, and tours.",
    "source_urls": [
      "https://www.clevelandohio.gov/explore/about-cleveland/history-facts",
      "https://case.edu/ech/articles/f/flats",
      "https://case.edu/ech/articles/o/ohio-city-city-ohio",
      "https://www.clevelandorchestra.com/learn/musical-arts-association"
    ]
  },
  "key_facts": [
    {
      "text": "The Connecticut Land Company’s survey established Cleveland in 1796; the city was named for General Moses Cleaveland and incorporated in 1836.",
      "source_urls": [
        "https://www.clevelandohio.gov/explore/about-cleveland/history-facts"
      ]
    },
    {
      "text": "The Flats are low-lying land along the Cuyahoga River; canals, lake shipping, and railways helped turn the area into a center for docks, warehouses, and factories.",
      "source_urls": [
        "https://case.edu/ech/articles/f/flats"
      ]
    },
    {
      "text": "Ohio City became an independent municipality in 1836 and was annexed by Cleveland in 1854.",
      "source_urls": [
        "https://case.edu/ech/articles/o/ohio-city-city-ohio"
      ]
    },
    {
      "text": "Ohio City’s West Side Market traces its beginnings to a public market site set aside in 1840; its present market building opened in 1912.",
      "source_urls": [
        "https://case.edu/ech/articles/o/ohio-city-city-ohio",
        "https://case.edu/ech/articles/w/west-side-market"
      ]
    },
    {
      "text": "The Cleveland Orchestra was founded in 1918; Severance became its permanent home in 1931, and the ensemble began touring Europe in 1957.",
      "source_urls": [
        "https://www.clevelandorchestra.com/learn/musical-arts-association"
      ]
    }
  ],
